      ('ks_payment_receipts','checkout_session_id:text:notnull,payment_intent_id:text:notnull,user_id:uuid:notnull,livemode:bool:notnull,tier:text:notnull,connections:int4:notnull,duration_days:int4:notnull,amount_cents:int4:notnull,currency:text:notnull,activated:bool:notnull,expires_at:timestamptz:nullable,recorded_at:timestamptz:notnull'),
      ('ks_setup_order_queue','checkout_session_id:text:notnull,payment_intent_id:text:notnull,user_id:uuid:notnull,livemode:bool:notnull,tier:text:notnull,connections:int4:notnull,duration_days:int4:notnull,amount_cents:int4:notnull,currency:text:notnull,fulfillment_status:text:notnull,queued_at:timestamptz:notnull')
    ) as reviewed(table_name,signature)
